export default {
    data: {
        heightsOfMountain: [],
    },
    onInit() {
        this.heightsOfMountain = [];
    },
    onShow() {
        prompt.showOpenFilePicker({
            types: [
                {
                    description: 'Text Files',
                    accept: ['text/plain'],
                },
            ],
            multiple: false,
        }).then((result) => {
            const file = result[0];
            const fileHandle = file.fileHandle;
            const fileReader = new FileReader();
            fileReader.readAsText(fileHandle);
            fileReader.onload = () => {
                const lines = fileReader.result.split('\n');
                for (const line of lines) {
                    this.heightsOfMountain.push(parseInt(line));
                }
                this.heightsOfMountain.sort((a, b) => b - a);
                console.log(this.heightsOfMountain[0]);
                console.log(this.heightsOfMountain[1]);
                console.log(this.heightsOfMountain[2]);
            };
        }).catch((err) => {
            console.error('Failed to open file: ' + err);
        });
    },
};

